import { describe, expect, it } from "vitest";
import { parseInline, parseMarkdown, safeHref, stripHtmlComments } from "./markdownParse";

describe("parseMarkdown", () => {
  it("renders a git-cliff changelog without the generator comment", () => {
    const src =
      "## [0.35.0] — 2026-11-07\n\n### Other\n- Reuse the image ([d365c15](https://github.com/sislelabs/kuso/commit/d365c15))\n\n<!-- generated by git-cliff -->\n";
    const blocks = parseMarkdown(src);
    expect(blocks.map((b) => b.type)).toEqual(["heading", "heading", "list"]);
    expect(JSON.stringify(blocks)).not.toContain("git-cliff");
    const list = blocks[2];
    if (list.type !== "list") throw new Error("expected list");
    expect(list.items[0]).toContainEqual({
      type: "link",
      href: "https://github.com/sislelabs/kuso/commit/d365c15",
      children: [{ type: "text", value: "d365c15" }],
    });
  });

  it("keeps raw HTML as text instead of markup", () => {
    const blocks = parseMarkdown("<img src=x onerror=alert(1)>");
    expect(blocks).toEqual([
      { type: "paragraph", children: [{ type: "text", value: "<img src=x onerror=alert(1)>" }] },
    ]);
  });

  it("parses ordered lists, fenced code and paragraphs", () => {
    const blocks = parseMarkdown("1. one\n2. two\n\n```\nkuso upgrade\n```\nplain\ntext");
    expect(blocks).toEqual([
      { type: "list", ordered: true, items: [[{ type: "text", value: "one" }], [{ type: "text", value: "two" }]] },
      { type: "code", value: "kuso upgrade" },
      { type: "paragraph", children: [{ type: "text", value: "plain text" }] },
    ]);
  });
});

describe("parseInline", () => {
  it("handles bold, code and emphasis", () => {
    expect(parseInline("**Breaking:** run `kuso upgrade` *now*")).toEqual([
      { type: "strong", children: [{ type: "text", value: "Breaking:" }] },
      { type: "text", value: " run " },
      { type: "code", value: "kuso upgrade" },
      { type: "text", value: " " },
      { type: "em", children: [{ type: "text", value: "now" }] },
    ]);
  });

  it("drops unsafe link targets but keeps the label", () => {
    expect(parseInline("[click](javascript:alert(1))")).toEqual([{ type: "text", value: "click" }]);
    expect(parseInline("[rel](/settings)")).toEqual([{ type: "text", value: "rel" }]);
  });

  it("does not treat snake_case as emphasis", () => {
    expect(parseInline("set max_parallel_builds")).toEqual([{ type: "text", value: "set max_parallel_builds" }]);
  });
});

describe("helpers", () => {
  it("strips multi-line and unterminated comments", () => {
    expect(stripHtmlComments("a<!-- x\ny -->b<!-- open")).toBe("ab");
  });
  it("only allows http(s) hrefs", () => {
    expect(safeHref("https://x.dev/a")).toBe("https://x.dev/a");
    expect(safeHref("data:text/html,hi")).toBeNull();
    expect(safeHref("javascript:alert(1)")).toBeNull();
  });
});
